mapper.select:
SELECT * FROM ( SELECT TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.XML_SEQ DESC) AS RNUM, A.XML_SEQ AS "xmlSeq", A.WORK_GUBUN AS "workGubun", A.XML_PROCESS_NAME AS "xmlProcessName", A.PROCESS_REMARK AS "processRemark", A.XML_INPUTPARAM AS "xmlInputParam", A.XML_OTPUTPARAM AS "xmlOutputParam", A.TEST_OK AS "testOk", B.CODE_NM AS "codeNm" FROM TB_SENDMESSAGETYPR A JOIN LETTCCMMNDETAILCODE B ON A.WORK_GUBUN = B.CODE WHERE 1=1
AND A.XML_PROCESS_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.PROCESS_REMARK LIKE CONCAT('%', #{searchKeyword}, '%')
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT XML_PROCESS_NAME
FROM TB_SENDMESSAGETYPR
WHERE ETC1 = #{code}

SELECT COALESCE(COUNT(*), 0)
FROM TB_SENDMESSAGETYPR
WHERE XML_PROCESS_NAME = #{xmlProcessName}
